/*	Decide - validates the submitted response against the stored row and the live event.	*/
/*	Nothing posted is trusted beyond the token: the row is re-read and the event re-queried.	*/

const cfg_obj = $('Config').first().json;
const sub_obj = $('Extract Submission').first().json;
const api_obj = $input.first().json;
const now_str = $now.toISO();

const rows_ary = $('Load Row').all().map(function (i_obj) { return i_obj.json; }).filter(function (r_obj) { return r_obj && r_obj.token; });
const row_obj = rows_ary.find(function (r_obj) { return String(r_obj.token) === String(sub_obj.offerToken); }) || null;

const event_obj = ((((api_obj.data || {}).events || {}).edges || [])[0] || {}).node || null;

const esc_fn = function (v_any)
{
	return String(v_any === null || v_any === undefined ? '' : v_any)
		.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
};

const pretty_fn = function (iso_str)
{
	if (!iso_str) { return ''; }
	const d_obj = new Date(String(iso_str).replace(' ', 'T'));
	if (isNaN(d_obj.getTime())) { return String(iso_str); }
	const months_ary = ['January','February','March','April','May','June','July','August','September','October','November','December'];
	return d_obj.getDate() + ' ' + months_ary[d_obj.getMonth()] + ' ' + d_obj.getFullYear();
};

const page_fn = function (title_str, body_str)
{
	return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc_fn(title_str) + '</title><style>' + cfg_obj.BRAND_CSS + '</style></head><body><header class="masthead"><p>' + esc_fn(cfg_obj.BRAND_NAME) + '</p></header><main>' + body_str + '</main></body></html>';
};

/*	Two shapes of non-form page. refuse is for something wrong, so it points at a human.
	closeOff is for when everything is in order and there is simply nothing left to do	*/
const refuse_fn = function (heading_str, message_str)
{
	return page_fn(heading_str, '<h1>' + esc_fn(heading_str) + '</h1><div class="notice error"><p>' + esc_fn(message_str) + '</p></div><p>Please reply to the offer email and someone will help.</p>');
};

const closeOff_fn = function (heading_str, message_str)
{
	return page_fn(heading_str, '<h1>' + esc_fn(heading_str) + '</h1><div class="notice"><p>' + esc_fn(message_str) + '</p></div><p>You can close this page.</p>');
};

const invalid_fn = function (heading_str, message_str, closed_bln)
{
	return [{ json: {
		valid: false,
		rowId: '',
		newStatus: '',
		outcome: 'invalid',
		resultHtml: closed_bln ? closeOff_fn(heading_str, message_str) : refuse_fn(heading_str, message_str)
	} }];
};

if (!row_obj)
{
	return invalid_fn('This link is no longer valid', 'We could not find this offer. It may have been withdrawn, or the link may be incomplete.', false);
}

const status_str = String(row_obj.status || '');

if (status_str === 'accepted')
{
	return invalid_fn('You have already accepted', 'Your place on ' + String(row_obj.event_title || 'this event') + ' is confirmed. Nothing further is needed.', true);
}

if (status_str === 'declined')
{
	return invalid_fn('You have already declined', 'We recorded that you did not want this place, and it has been offered to somebody else. If that has changed, reply to the offer email and we will pick it up.', true);
}

if (status_str === 'expired')
{
	return invalid_fn('This offer has expired', 'The place was held for a limited time and has now passed to the next person on the waitlist.', true);
}

if (status_str !== 'offered')
{
	return invalid_fn('This link is no longer valid', 'This offer is not open for a response.', false);
}

if (row_obj.expires_at && DateTime.fromISO(String(row_obj.expires_at)) < DateTime.fromISO(now_str))
{
	return [{ json: {
		valid: false,
		rowId: row_obj.id,
		newStatus: 'expired',
		outcome: 'invalid',
		resultHtml: closeOff_fn('This offer has expired', 'The place was held for a limited time and has now passed to the next person on the waitlist.')
	} }];
}

const accept_bln = String(sub_obj.action) === String(cfg_obj.ACCEPT_ACTION);
const decline_bln = String(sub_obj.action) === String(cfg_obj.DECLINE_ACTION);

if (!accept_bln && !decline_bln)
{
	return invalid_fn('We could not record that response', 'That answer was not one of the options offered.', false);
}

/*	Capacity is re-checked at submit time, not at offer time. Somebody else may have
	been registered in between, and accepting into a full event would oversell it	*/
const max_num = Number((event_obj || {}).maxPlaces || 0);
const reg_num = Number(((((event_obj || {}).learners || {}).pageInfo || {}).totalRecords) || 0);

if (accept_bln && event_obj && max_num > 0 && reg_num >= max_num)
{
	return [{ json: {
		valid: false,
		rowId: row_obj.id,
		newStatus: 'expired',
		outcome: 'invalid',
		resultHtml: closeOff_fn('This event is now full', 'Somebody else took the last place before we heard from you, so this offer can no longer be honoured. Thank you for considering it.')
	} }];
}

const title_str = String(row_obj.event_title || (event_obj || {}).title || 'this event');
const when_str = pretty_fn((event_obj || {}).start);
const meta_str = when_str ? '<p class="meta"><span>' + esc_fn(when_str) + '</span></p>' : '';

const acceptedHtml_str = page_fn('Your place is confirmed',
	'<h1>Your place is confirmed</h1>' + meta_str
	+ '<div class="notice"><p>You are booked onto <strong>' + esc_fn(title_str) + '</strong>. Joining details will follow by email.</p></div>'
	+ '<p>You can close this page.</p>');

const declinedHtml_str = page_fn('Thank you for letting us know',
	'<h1>Thank you for letting us know</h1>' + meta_str
	+ '<div class="notice"><p>We have released your place on <strong>' + esc_fn(title_str) + '</strong> and will offer it to the next person on the waitlist.</p></div>'
	+ '<p>You can close this page.</p>');

/*	Neutral rather than an error. The person did nothing wrong, their answer is recorded,
	and a human finishes it	*/
const acceptProblemHtml_str = page_fn('Thank you, we have your answer',
	'<h1>Thank you, we have your answer</h1>' + meta_str
	+ '<div class="notice"><p>We have recorded that you want the place on <strong>' + esc_fn(title_str) + '</strong>, but we could not confirm the booking automatically. Our team has been told and will finish it for you.</p></div>'
	+ '<p>You can close this page.</p>');

return [{ json: {
	valid: true,
	outcome: accept_bln ? 'accept' : 'decline',
	rowId: row_obj.id,
	newStatus: accept_bln ? 'accepted' : 'declined',
	eventId: String(row_obj.event_id || ''),
	eventTitle: title_str,
	contactId: String(row_obj.contact_id || ''),
	opportunityId: String(row_obj.opportunity_id || ''),
	now: now_str,
	acceptedHtml: acceptedHtml_str,
	declinedHtml: declinedHtml_str,
	acceptProblemHtml: acceptProblemHtml_str
} }];

