(function ()
{
	/*	The accept branch releases the offer hold because the registration does not consume it.
		extendReservations reports errors [] when it silently does nothing, so the release is
		judged on the hold read back rather than on the mutation response	*/
	const cfg_obj = $('Config').first().json;
	const dec_obj = $('Decide').first().json;
	const node_obj = ((((($json.data || {}).opportunities || {}).edges || [])[0] || {}).node) || {};
	const progErr_ary = (((($('Progress Opportunity to Won').first().json.data || {}).opportunities || {}).progress || {}).errors) || [];
	const relErr_ary = (((($('Release Hold on Accept').first().json.data || {}).opportunities || {}).extendReservations || {}).errors) || [];
	const held_bln = node_obj.isReservationValid === true && node_obj.reservationsValidUntil != null && DateTime.fromISO(node_obj.reservationsValidUntil) > $now;
	const tail_str = held_bln
		? ' THE OFFER HOLD WAS NOT RELEASED and is still live, so this seat is held twice until it lapses. remainingPlaces is understated and the next person on the waitlist will not be offered a place that is genuinely free. Fix: run extendReservations on this opportunity with reservationsValidUntil set to now, then check remainingPlaces on the event.'
		: ' The offer hold was released and read back as no longer valid, so the seat is not counted twice.';

	return JSON.stringify({
		query: 'mutation Log($originIdentifier: String!, $nodeId: ID!, $message: String!, $status: ExternalLogTypeStatus!, $payload: String) { externalLog { createExternalIntegrationLog(input: { originIdentifier: $originIdentifier, nodeId: $nodeId, message: $message, status: $status, payload: $payload }) { errors { label message value } } } }',
		variables: {
			originIdentifier: cfg_obj.ORIGIN_IDENTIFIER,
			nodeId: dec_obj.eventId,
			message: 'Waitlist offer ACCEPTED via the response form. Contact ' + dec_obj.contactId + ' registered on the event and the opportunity progressed to Won.' + tail_str,
			status: (progErr_ary.length > 0 || relErr_ary.length > 0 || held_bln) ? 'partial' : 'success',
			payload: JSON.stringify({ eventId: dec_obj.eventId, contactId: dec_obj.contactId, opportunityId: dec_obj.opportunityId, progressErrors: progErr_ary, releaseErrors: relErr_ary, holdAfterRelease: node_obj })
		}
	});
})()
}}

