		variables: {
			originIdentifier: cfg_obj.ORIGIN_IDENTIFIER,
			nodeId: dec_obj.eventId,
			message: 'Waitlist offer DECLINED via the response form by contact ' + dec_obj.contactId + '.' + tail_str,
			status: (relErr_ary.length > 0 || held_bln) ? 'partial' : 'success',
			payload: JSON.stringify({ eventId: dec_obj.eventId, contactId: dec_obj.contactId, opportunityId: dec_obj.opportunityId, releaseErrors: relErr_ary, holdAfterRelease: node_obj })
		}
	});
})()
